## C: Custom accessor on `pd.DataFrame`

This is very useful for assigning properties, and for ephemeral access to the wide dataframe. This type is more useful to bring in context for the QDF (functions, types, checks, index-magics) rather than use for managing the relation between a QDF and a wide dataframe.

```
@pd.api.extensions.register_dataframe_accessor("qdf")
class QDFAccessor:
    def __init__(self, df: QuantamentalDataFrame):
        self._validate(df)
        self._df = piv_df(df)

    @staticmethod
    def _validate(df: QuantamentalDataFrame):
        if not isinstance(df, QuantamentalDataFrame):
            raise TypeError("Must be a QuantamentalDataFrame")

    @property
    def df(self) -> pd.DataFrame:
        return self._df

    def reduce_df(
        self,
        metrics: Optional[List[str]] = None,
        cids: Optional[List[str]] = None,
        xcats: Optional[List[str]] = None,
        start: Optional[str] = None,
        end: Optional[str] = None,
    ) -> QuantamentalDataFrame:
        return reduce_df_for_wide(
            wdf=self._df,
            metrics=metrics,
            cids=cids,
            xcats=xcats,
            start=start,
            end=end,
        )

dfx = test_df()

rdf = dfx.qdf.reduce_df(
    metrics=["value"],
    cids=["AAA", "BBB"],
    tickers=["ABC_CRY"],
)
```

